package com.example.domain.model.i18n

internal object DuaNe1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("निद्राबाट ब्युँझँदा", "सम्पूर्ण प्रशंसा अल्लाहका लागि हो, जसले हामीलाई मृत्यु (निद्रा) पछि जीवन दिनुभयो, र उहाँकै तर्फ फर्केर जानु छ।", "निद्राबाट ब्युँझनेबित्तिकै अल्लाहको धन्यवाद गर्नका लागि।", "नबी ﷺ ब्युँझँदा यो दुआ पढ्नुहुन्थ्यो — दिनको सुरुवात कृतज्ञता र आखिरतको सम्झनाले।"),
        "dua_leaving_home" to DuaText("घरबाट निस्कँदा", "अल्लाहको नाममा; मैले अल्लाहमाथि भरोसा गरेँ। अल्लाहबिना न कुनै शक्ति छ न कुनै सामर्थ्य।", "घरबाहिर पाइला राख्दा अल्लाहको सुरक्षाका लागि।", "फरिश्ताहरू भन्छन्: 'तिमीलाई मार्गदर्शन दिइयो, तिम्रो हेरचाह गरियो र तिमीलाई बचाइयो', र शैतान टाढा जान्छ।"),
        "dua_anxiety_distress" to DuaText("चिन्ता र दुःखबाट मुक्ति", "हे अल्लाह! म चिन्ता र दुःखबाट, कमजोरी र अल्छीपनबाट, कन्जुसी र कायरताबाट, ऋणको भार र मानिसहरूको प्रभुत्वबाट तपाईंको शरण माग्छु।", "दुःख, चिन्ता, ऋणको भार र मानसिक पीडाको समयमा।", "नबी ﷺ यो दुआ धेरै गर्नुहुन्थ्यो — दुःख, अल्छीपन र ऋणको चिन्ताबाट शरण।"),
        "dua_sayyidul_istighfar" to DuaText("सय्यिदुल इस्तिगफार", "हे अल्लाह! तपाईं नै मेरो रब हुनुहुन्छ, तपाईंबाहेक कोही पूज्य छैन। तपाईंले मलाई सृष्टि गर्नुभयो र म तपाईंको दास हुँ, र म आफ्नो क्षमताअनुसार तपाईंको वाचा र प्रतिज्ञामा कायम छु। मैले गरेका कर्मको खराबीबाट तपाईंको शरण माग्छु। ममाथि तपाईंका कृपाहरू र मेरा पापहरू स्वीकार गर्छु, त्यसैले मलाई क्षमा गर्नुहोस्, किनकि तपाईंबाहेक कसैले पाप क्षमा गर्दैन।", "बिहान र साँझ — नबी ﷺ ले सिकाउनुभएको तौबाको सर्वोत्तम दुआ।", "जसले दृढ विश्वासका साथ साँझ पढ्छ र त्यही रात मर्छ ऊ जन्नतमा जान्छ; बिहान पढ्दा पनि यही फाइदा।"),
        "dua_parents" to DuaText("आमाबुबाका लागि दुआ", "हे मेरा रब! उहाँहरू दुवैमाथि दया गर्नुहोस्, जसरी उहाँहरूले बाल्यकालमा मलाई हुर्काउनुभयो।", "आमाबुबाका लागि कुरआनी दुआ — बाल्यकालको पालनपोषणको बदलामा।", "अल्लाहले आफैँ आमाबुबाका लागि यो दुआ गर्न आदेश दिनुभयो।"),
        "dua_entering_mosque" to DuaText("मस्जिदमा प्रवेश", "हे अल्लाह! मेरा लागि तपाईंको कृपाका ढोकाहरू खोलिदिनुहोस्।", "दायाँ खुट्टा राखेर मस्जिदमा प्रवेश गर्दा।", "नबी ﷺ ले मस्जिदमा प्रवेश गर्दा यो दुआ पढ्ने शिक्षा दिनुभयो।"),
        "dua_morning_asbahna" to DuaText("बिहानको जिक्र", "हामीले बिहान गर्यौँ र सम्पूर्ण राज्यले पनि अल्लाहका लागि बिहान गर्यो। सम्पूर्ण प्रशंसा अल्लाहका लागि हो। अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन। राज्य उहाँकै हो, प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "बिहान पढिने मसनून दुआ।", "दिनको सुरुवात अल्लाहको राज्य र तौहीदको स्वीकृतिले हुन्छ।"),
        "dua_evening_amsayna" to DuaText("साँझको जिक्र", "हामीले साँझ गर्यौँ र सम्पूर्ण राज्यले पनि अल्लाहका लागि साँझ गर्यो। सम्पूर्ण प्रशंसा अल्लाहका लागि हो। अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन। राज्य उहाँकै हो, प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "साँझ पढिने मसनून दुआ।", "रातको सुरुवात अल्लाहको राज्य र तौहीदको स्वीकृतिले हुन्छ।"),
        "dua_bismillah_la_yadurru" to DuaText("सबै हानिबाट सुरक्षा", "अल्लाहको नाममा, जसको नामसँग पृथ्वी र आकाशमा कुनै कुराले हानि गर्न सक्दैन, र उहाँ सबै सुन्ने, सबै जान्ने हुनुहुन्छ।", "बिहान र साँझ तीन-तीन पटक।", "जसले बिहान-साँझ तीन पटक पढ्छ, उसलाई कुनै कुराले हानि गर्दैन।"),
        "dua_raditu_billahi" to DuaText("अल्लाहलाई रबको रूपमा सन्तुष्ट", "म अल्लाहलाई रब, इस्लामलाई दीन र मुहम्मद ﷺ लाई नबीको रूपमा पाएर सन्तुष्ट छु।", "बिहान र साँझ तीन पटक।", "कयामतको दिन उसलाई सन्तुष्ट पार्नु अल्लाहमाथि उसको हक बन्छ।"),
        "dua_hasbiyallah" to DuaText("हस्बियल्लाह (अल्लाह पर्याप्त हुनुहुन्छ)", "मलाई अल्लाह पर्याप्त हुनुहुन्छ, उहाँबाहेक कोही पूज्य छैन, उहाँमाथि नै मैले भरोसा गरेँ र उहाँ महान अर्शका रब हुनुहुन्छ।", "बिहान र साँझ सात पटक।", "कुरआनको आयत; संसार र आखिरतका चिन्तामा अल्लाह पर्याप्त हुनुहुन्छ।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुब्हानल्लाहि व बिहम्दिही", "अल्लाह पवित्र हुनुहुन्छ र सम्पूर्ण प्रशंसा उहाँकै हो।", "दिनमा सय पटक।", "जसले दिनमा सय पटक भन्छ, उसका पाप क्षमा हुन्छन्, चाहे समुद्रको फिँजजत्ति नै किन नहोस्।"),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वहदहू", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन। राज्य र प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "दिनमा सय पटक पढ्दाको ठूलो पुण्य।", "दस दास मुक्त गरेको पुण्य, सय पुण्य, सय पाप क्षमा र साँझसम्म शैतानबाट सुरक्षा।"),
        "dua_leaving_mosque" to DuaText("मस्जिदबाट निस्कँदा", "हे अल्लाह! म तपाईंसँग तपाईंको अनुग्रह माग्छु।", "बायाँ खुट्टा बाहिर निकालेर मस्जिदबाट निस्कँदा।", "मस्जिदबाट निस्कँदा अल्लाहको अनुग्रह र जीविकाको माग।"),
        "dua_after_adhan" to DuaText("अजानपछि", "हे अल्लाह! यो पूर्ण आह्वान र कायम हुन लागेको नमाजका रब! मुहम्मद ﷺ लाई वसीला र श्रेष्ठता प्रदान गर्नुहोस्, र उहाँलाई त्यस प्रशंसित स्थानमा पुर्याउनुहोस् जसको वाचा तपाईंले उहाँसँग गर्नुभएको छ।", "अजान पूरा भएपछि।", "जसले यो दुआ पढ्छ, कयामतको दिन उसका लागि नबी ﷺ को सिफारिस निश्चित हुन्छ।"),
        "dua_after_salah_istighfar" to DuaText("फर्ज नमाजपछि", "म अल्लाहसँग क्षमा माग्छु (३ पटक)। हे अल्लाह! तपाईं नै सलाम हुनुहुन्छ र तपाईंबाटै शान्ति छ, तपाईं बरकतमय हुनुहुन्छ हे महिमा र सम्मानका स्वामी।", "सलाम फेरेलगत्तै।", "नबी ﷺ हरेक फर्ज नमाजपछि यो पढ्नुहुन्थ्यो।"),
        "dua_after_salah_help_dhikr" to DuaText("तपाईंको जिक्रमा मलाई मद्दत गर्नुहोस्", "हे अल्लाह! तपाईंको जिक्र, तपाईंको धन्यवाद र तपाईंको उत्तम उपासनामा मलाई मद्दत गर्नुहोस्।", "हरेक नमाजपछि — नबी ﷺ ले मुआज (र.) लाई उपदेश दिनुभयो।", "नबी ﷺ को विशेष उपदेश — उपासनामा सुन्दरता र निरन्तरता।"),
        "dua_ayatul_kursi" to DuaText("नमाजपछि आयतुल कुर्सी", "अल्लाह, उहाँबाहेक कोही पूज्य छैन, उहाँ सदा जीवित, सबैका धारक हुनुहुन्छ। उहाँलाई न उँघ लाग्छ न निद्रा। आकाश र पृथ्वीमा जे छ सबै उहाँकै हो। उहाँको अनुमतिबिना उहाँसमक्ष कसले सिफारिस गर्न सक्छ? उहाँ जान्नुहुन्छ जे तिनीहरूका अगाडि र पछाडि छ, र तिनीहरूले उहाँको ज्ञानबाट केही पनि समेट्न सक्दैनन्, जति उहाँ चाहनुहुन्छ त्यति बाहेक। उहाँको कुर्सीले आकाश र पृथ्वीलाई घेरेको छ, र तिनको रक्षाले उहाँलाई थकाउँदैन, उहाँ सर्वोच्च, महान हुनुहुन्छ।", "हरेक फर्ज नमाजपछि र सुत्नुअघि।", "हरेक फर्ज नमाजपछि पढ्नेलाई जन्नत जानबाट मृत्युले मात्र रोक्छ; सुत्नुअघि पढ्दा बिहानसम्म सुरक्षा।"),
        "dua_before_sleep" to DuaText("सुत्नुअघि", "हे अल्लाह! तपाईंकै नाममा म मर्छु (सुत्छु) र बाँच्छु (ब्युँझन्छु)।", "ओछ्यानमा पल्टेपछि।", "नबी ﷺ सुत्नुअघि यो दुआ पढ्नुहुन्थ्यो।"),
        "dua_sleep_tasbeeh" to DuaText("सुत्नुअघि तस्बीह-ए-फातिमी", "अल्लाह पवित्र हुनुहुन्छ (३३), सम्पूर्ण प्रशंसा अल्लाहका लागि (३३), अल्लाह सबैभन्दा महान हुनुहुन्छ (३४)।", "सुत्नुअघि — नबी ﷺ ले फातिमा र अली (र.) लाई सिकाउनुभयो।", "नबी ﷺ ले भन्नुभयो यो तिमीहरूका लागि नोकरभन्दा उत्तम हो।"),
        "dua_sleep_qina_adhab" to DuaText("सजायबाट सुरक्षा", "हे अल्लाह! जुन दिन तपाईंले आफ्ना दासहरूलाई उठाउनुहुनेछ, त्यस दिन मलाई आफ्नो सजायबाट बचाउनुहोस्।", "दायाँ हात गालामुनि राखेर तीन पटक।", "निद्रालाई मृत्युको सम्झना र आखिरतको तयारी बनाउँछ।"),
        "dua_bad_dream" to DuaText("नराम्रो सपना देख्दा", "म धिक्कारिएको शैतानबाट अल्लाहको शरण माग्छु।", "नराम्रो सपना देख्दा: बायाँतिर तीन पटक हल्का थुक्नुहोस्, अनि कोल्टे फेर्नुहोस्।", "नराम्रो सपनाले हानि गर्दैन; कसैलाई नभन्नुहोस्।"),
        "dua_yunus" to DuaText("युनुस (अ.) को दुआ", "तपाईंबाहेक कोही पूज्य छैन, तपाईं पवित्र हुनुहुन्छ, निश्चय नै म अन्यायीहरूमध्येको थिएँ।", "माछाको पेटमा युनुस (अ.) को दुआ — हरेक संकटमा।", "जुन मुस्लिमले जुनसुकै विषयमा यो दुआ गर्छ, अल्लाहले उसको दुआ स्वीकार गर्नुहुन्छ।"),
        "dua_karb" to DuaText("कठिन संकटको दुआ", "अल्लाहबाहेक कोही पूज्य छैन, जो महान, सहनशील हुनुहुन्छ। अल्लाहबाहेक कोही पूज्य छैन, जो महान अर्शका रब हुनुहुन्छ। अल्लाहबाहेक कोही पूज्य छैन, जो आकाशहरूका रब, पृथ्वीका रब र सम्मानित अर्शका रब हुनुहुन्छ।", "कठिन संकट र पीडाको समयमा।", "नबी ﷺ संकटको समयमा यो दुआ पढ्नुहुन्थ्यो।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हय्यु या कय्यूम", "हे सदा जीवित, हे सबैका धारक! तपाईंको कृपाको आधारमा म सहायता माग्छु।", "जब कुनै कुरा धेरै भारी हुन्छ।", "कुनै कुराले नबी ﷺ लाई चिन्तित बनाउँदा उहाँ यो पढ्नुहुन्थ्यो।"),
        "dua_hasbunallah" to DuaText("हस्बुनल्लाहु व निअमल वकील", "हामीलाई अल्लाह पर्याप्त हुनुहुन्छ र उहाँ उत्तम कार्यसाधक हुनुहुन्छ।", "शत्रुको डर वा ठूलो खतराको समयमा।", "इब्राहीम (अ.) लाई आगोमा फालिँदा र नबी ﷺ ले खतराको समयमा यो भन्नुभयो।"),
        "dua_entering_home" to DuaText("घरमा प्रवेश", "अल्लाहको नाममा।", "घरमा प्रवेश गर्दा अल्लाहको नाम लिनुहोस् र सलाम गर्नुहोस्।", "घरमा प्रवेश गर्दा र खाँदा अल्लाहको जिक्र गरे शैतान भन्छ: यहाँ तिमीहरूका लागि न रात बिताउने ठाउँ छ न खाना।"),
        "dua_travel" to DuaText("यात्राको (सवारीको) दुआ", "पवित्र हुनुहुन्छ उहाँ जसले यसलाई हाम्रो वशमा गरिदिनुभयो, नत्र हामी यसलाई वशमा राख्न सक्दैनथ्यौँ, र निश्चय नै हामी आफ्ना रबतर्फ फर्कनेवाला छौँ।", "सवारीमा बसेर तीन पटक अल्लाहु अकबर भनेपछि।", "यात्राको मसनून दुआ — सुरक्षा र बरकतका लागि।"),
        "dua_entering_market" to DuaText("बजारमा प्रवेश", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन। राज्य र प्रशंसा उहाँकै हो। उहाँ नै जीवन दिनुहुन्छ र मृत्यु दिनुहुन्छ, र उहाँ स्वयं सदा जीवित हुनुहुन्छ, कहिल्यै मर्नुहुन्न। उहाँकै हातमा भलाइ छ र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "बजारमा प्रवेश गर्दा।", "हदीसमा यसको ठूलो पुण्य बताइएको छ (लाखौँ पुण्य)।"),
        "dua_adam_forgiveness" to DuaText("आदम (अ.) को दुआ", "हे हाम्रा रब! हामीले आफैँमाथि अन्याय गर्यौँ, र यदि तपाईंले हामीलाई क्षमा गर्नुभएन र दया गर्नुभएन भने हामी अवश्य घाटा उठाउनेहरूमध्ये हुनेछौँ।", "आदम र हव्वा (अ.) को तौबाको दुआ।", "मानवजातिको पहिलो तौबा — अल्लाहले यसलाई स्वीकार गर्नुभयो।"),
        "dua_abu_bakr" to DuaText("अबू बक्र (र.) लाई सिकाइएको दुआ", "हे अल्लाह! मैले आफैँमाथि धेरै अन्याय गरेँ, र तपाईंबाहेक कसैले पाप क्षमा गर्दैन, त्यसैले आफ्नो तर्फबाट मलाई क्षमा गर्नुहोस् र ममाथि दया गर्नुहोस्, निश्चय नै तपाईं क्षमाशील, दयालु हुनुहुन्छ।", "नमाजमा (तशह्हुदपछि) पढ्न नबी ﷺ ले अबू बक्र सिद्दीक (र.) लाई सिकाउनुभयो।", "नमाजको अन्त्यमा पढिने मसनून दुआ।"),
        "dua_astaghfirullah_atubu" to DuaText("दैनिक इस्तिगफार", "म अल्लाहसँग क्षमा माग्छु र उहाँतर्फ तौबा गर्छु।", "नबी ﷺ दिनमा सत्तरी पटकभन्दा बढी इस्तिगफार गर्नुहुन्थ्यो।", "नबी ﷺ ले भन्नुभयो: म दिनमा सत्तरी पटकभन्दा बढी अल्लाहसँग क्षमा माग्छु र तौबा गर्छु।"),
        "dua_laylatul_qadr" to DuaText("लैलतुल कद्रको दुआ", "हे अल्लाह! तपाईं अत्यन्त क्षमाशील हुनुहुन्छ, क्षमा गर्न मन पराउनुहुन्छ, त्यसैले मलाई क्षमा गर्नुहोस्।", "आइशा (र.) लाई लैलतुल कद्रका लागि सिकाइएको।", "रमजानका अन्तिम रातहरू र लैलतुल कद्रको विशेष दुआ।"),
        "dua_family_coolness" to DuaText("आँखाको शीतलता (श्रीमती-सन्तान)", "हे हाम्रा रब! हामीलाई हाम्रा श्रीमती र सन्तानबाट आँखाको शीतलता दिनुहोस्, र हामीलाई धर्मपरायणहरूको इमाम बनाउनुहोस्।", "असल श्रीमती/श्रीमान र सन्तानका लागि कुरआनी दुआ।", "घरमा शान्ति र असल सन्तानका लागि।"),
        "dua_righteous_children" to DuaText("असल सन्तानका लागि", "हे मेरा रब! आफ्नो तर्फबाट मलाई पवित्र सन्तान दिनुहोस्, निश्चय नै तपाईं दुआ सुन्नुहुने हुनुहुन्छ।", "जकरिया (अ.) को दुआ।", "सन्तान माग्नका लागि कुरआनी दुआ।"),
        "dua_ibrahim_prayer_family" to DuaText("नमाज कायम गर्नेहरू", "हे मेरा रब! मलाई र मेरा सन्तानलाई नमाज कायम गर्ने बनाउनुहोस्। हे हाम्रा रब! मेरो दुआ स्वीकार गर्नुहोस्। हे हाम्रा रब! हिसाबको दिन मलाई, मेरा आमाबुबालाई र सबै मोमिनहरूलाई क्षमा गर्नुहोस्।", "इब्राहीम (अ.) को आफ्नो र सन्तानका लागि दुआ।", "सामान्यतया नमाजको अन्त्यमा पढिन्छ।"),
        "dua_newlywed" to DuaText("नवदम्पतीलाई शुभकामना", "अल्लाहले तिम्रा लागि बरकत देऊन्, तिमीमाथि बरकत बर्साऊन् र तिमी दुवैलाई भलाइमा एकसाथ राखून्।", "निकाह गर्नेलाई शुभकामना दिँदा।", "निकाहको मसनून शुभकामना।"),
        "dua_before_eating" to DuaText("खानाअघि", "अल्लाहको नाममा। (बिर्सिएमा:) अल्लाहको नाममा, यसको सुरु र अन्त्यमा।", "खानाअघि। बिर्सिएमा बीचमा पढ्नुहोस्।", "बिस्मिल्लाह पढ्दा खानामा शैतान साझेदार हुँदैन।"),
        "dua_after_eating" to DuaText("खानापछि", "सम्पूर्ण प्रशंसा अल्लाहका लागि जसले मलाई यो खुवाउनुभयो र मेरो कुनै शक्ति र सामर्थ्यबिना मलाई यो जीविका दिनुभयो।", "खाना सकिएपछि।", "पढ्नेका पहिलेका पाप क्षमा हुन्छन्।"),
        "dua_host" to DuaText("आतिथेयका लागि", "हे अल्लाह! तपाईंले उनीहरूलाई दिएको जीविकामा बरकत दिनुहोस्, उनीहरूलाई क्षमा गर्नुहोस् र उनीहरूमाथि दया गर्नुहोस्।", "कसैको घरमा खाएपछि आतिथेयका लागि।", "मसनून तरिकाले आतिथेयलाई धन्यवाद।"),
        "dua_breaking_fast" to DuaText("रोजा खोल्दा", "तिर्खा मेटियो, नसाहरू भिजे र अल्लाहले चाहे प्रतिफल निश्चित भयो।", "इफ्तारको समयमा।", "नबी ﷺ इफ्तारको समयमा यो भन्नुहुन्थ्यो।"),
        "dua_new_clothes" to DuaText("नयाँ लुगा लगाउँदा", "हे अल्लाह! सम्पूर्ण प्रशंसा तपाईंकै लागि हो, तपाईंले नै मलाई यो लगाइदिनुभयो। म तपाईंसँग यसको भलाइ र जुन कामका लागि यो बनाइएको हो त्यसको भलाइ माग्छु, र यसको खराबी र जुन कामका लागि बनाइएको हो त्यसको खराबीबाट तपाईंको शरण माग्छु।", "नयाँ लुगा लगाउँदा (लुगाको नाम लिएर, जस्तै कुर्ता वा पगडी)।", "नबी ﷺ नयाँ लुगा लगाउँदा यो दुआ गर्नुहुन्थ्यो। (दैनिक लुगा लगाउने दुआ 'लुगा लगाउँदा' मा छ।)"),
        "dua_rabbana_atina" to DuaText("संसार र आखिरतको भलाइ", "हे हाम्रा रब! हामीलाई संसारमा पनि भलाइ दिनुहोस् र आखिरतमा पनि भलाइ दिनुहोस्, र हामीलाई आगोको सजायबाट बचाउनुहोस्।", "नबी ﷺ सबैभन्दा बढी यो दुआ गर्नुहुन्थ्यो।", "संसार र आखिरतका सबै भलाइ समेट्ने दुआ।"),
        "dua_rabbi_zidni_ilma" to DuaText("ज्ञानमा वृद्धि", "हे मेरा रब! मेरो ज्ञान बढाइदिनुहोस्।", "ज्ञानमा वृद्धिका लागि।", "अल्लाहले नबी ﷺ लाई ज्ञानमा वृद्धिको मात्र दुआ गर्न आदेश दिनुभयो।"),
        "dua_musa_sharh_sadr" to DuaText("छाती खोल्ने दुआ (मूसा अ.)", "हे मेरा रब! मेरो छाती खोलिदिनुहोस्, मेरो काम सजिलो पारिदिनुहोस्, र मेरो जिब्रोको गाँठो फुकाइदिनुहोस् ताकि मानिसहरूले मेरो कुरा बुझून्।", "परीक्षा, भाषण वा कुनै कठिन कामअघि।", "मूसा (अ.) को दुआ — मनको शान्ति र काममा सहजता।"),
        "dua_la_tuzigh" to DuaText("हृदयको दृढता", "हे हाम्रा रब! मार्गदर्शन दिएपछि हाम्रा हृदयहरूलाई टेढो नपार्नुहोस्, र हामीलाई आफ्नो तर्फबाट कृपा दिनुहोस्, निश्चय नै तपाईं अत्यन्त दाता हुनुहुन्छ।", "मार्गदर्शनमा दृढ रहनका लागि।", "ईमानमा दृढ रहने दुआ।"),
        "dua_ya_muqallib" to DuaText("हे हृदय फेर्नुहुने", "हे हृदयहरू फेर्नुहुने! मेरो हृदयलाई आफ्नो दीनमा दृढ राख्नुहोस्।", "नबी ﷺ प्रायः यो दुआ गर्नुहुन्थ्यो।", "उम्मे सलमा (र.) का अनुसार नबी ﷺ को सबैभन्दा बढी गरिने दुआ।"),
        "dua_la_tuakhidhna" to DuaText("सूरह बकराका अन्तिम आयतहरू", "हे हाम्रा रब! यदि हामीले बिर्स्यौँ वा गल्ती गर्यौँ भने हामीलाई नसमात्नुहोस्। हे हाम्रा रब! हामीमाथि त्यस्तो भार नराख्नुहोस् जस्तो हामीभन्दा अघिकाहरूमाथि राख्नुभयो। हे हाम्रा रब! हामीमाथि त्यो भार नराख्नुहोस् जसको शक्ति हामीसँग छैन। हामीलाई माफ गर्नुहोस्, क्षमा गर्नुहोस् र हामीमाथि दया गर्नुहोस्। तपाईं नै हाम्रा संरक्षक हुनुहुन्छ, त्यसैले काफिर समुदायविरुद्ध हामीलाई मद्दत गर्नुहोस्।", "राति सुत्नुअघि — सूरह बकराका अन्तिम दुई आयत।", "जसले राति सूरह बकराका अन्तिम दुई आयत पढ्छ, ती उसका लागि पर्याप्त हुन्छन्।"),
        "dua_visiting_sick" to DuaText("बिरामी भेट्न जाँदा", "म महान अल्लाहसँग, जो महान अर्शका रब हुनुहुन्छ, प्रार्थना गर्छु कि उहाँले तिमीलाई निको पारून्।", "बिरामी भेट्दा सात पटक।", "मृत्युको समय नआएको भए अल्लाहले उसलाई निको पार्नुहुन्छ।"),
        "dua_ruqyah_pain" to DuaText("शारीरिक दुखाइका लागि", "म अल्लाह र उहाँको शक्तिको शरण माग्छु त्यो पीडाको खराबीबाट जुन म महसुस गर्छु र जसको मलाई डर छ।", "दुखेको ठाउँमा हात राखेर तीन पटक बिस्मिल्लाह, अनि सात पटक यो दुआ।", "नबी ﷺ ले उस्मान बिन अबिल आस (र.) लाई दुखाइका लागि सिकाउनुभयो।"),
        "dua_ruqyah_nabawi" to DuaText("बिरामीका लागि नबवी रुक्या", "हे अल्लाह, मानिसहरूका रब! पीडा हटाउनुहोस्, निको पार्नुहोस्, तपाईं नै निको पार्नुहुने हुनुहुन्छ, तपाईंको उपचारबाहेक कुनै उपचार छैन, यस्तो उपचार जसले कुनै रोग बाँकी नराखोस्।", "बिरामीमाथि हात फेरेर।", "नबी ﷺ आफ्ना परिवारका बिरामी भेट्दा यो पढ्नुहुन्थ्यो।"),
        "dua_kalimat_tammat" to DuaText("पूर्ण वचनहरूको शरण", "म अल्लाहका पूर्ण वचनहरूको शरण माग्छु उहाँले सृष्टि गर्नुभएका हरेक कुराको खराबीबाट।", "कुनै ठाउँमा बास बस्दा वा साँझ।", "जसले कुनै ठाउँमा ओर्लेर यो पढ्छ, त्यहाँबाट नजाउन्जेल कुनै कुराले उसलाई हानि गर्दैन।"),
        "dua_evil_eye" to DuaText("बालबालिकाको सुरक्षा (नजर)", "म तिमी दुवैलाई अल्लाहका पूर्ण वचनहरूको शरणमा दिन्छु हरेक शैतान र विषालु जनावरबाट, र हरेक हानिकारक नजरबाट।", "नबी ﷺ हसन र हुसैन (र.) माथि यो फुक्नुहुन्थ्यो।", "बालबालिकालाई नजर र खराबीबाट बचाउने मसनून दुआ (एक बच्चाका लागि 'उईजुका')।"),
        "dua_seeing_afflicted" to DuaText("कसैलाई संकटमा देख्दा", "सम्पूर्ण प्रशंसा अल्लाहका लागि जसले मलाई त्यसबाट सुरक्षित राख्नुभयो जसमा तिमीलाई परीक्षा गर्नुभयो, र मलाई उहाँका धेरै सृष्टिमाथि श्रेष्ठता दिनुभयो।", "कसैलाई संकटमा देख्दा (मनमनै पढ्नुहोस्)।", "पढ्ने व्यक्ति त्यो संकटबाट सुरक्षित रहन्छ।"),
        "dua_istikhara" to DuaText("सलातुल इस्तिखारा", "हे अल्लाह! म तपाईंको ज्ञानद्वारा तपाईंसँग भलाइ माग्छु, तपाईंको शक्तिद्वारा सामर्थ्य माग्छु, र तपाईंको महान अनुग्रहको याचना गर्छु। तपाईं सक्षम हुनुहुन्छ म होइन, तपाईं जान्नुहुन्छ म जान्दिनँ, र तपाईं अदृश्यका पूर्ण ज्ञाता हुनुहुन्छ। हे अल्लाह! यदि तपाईंको ज्ञानमा यो काम (आफ्नो काम मनमा ल्याउनुहोस्) मेरो दीन, जीवन र परिणामका लागि राम्रो छ भने यसलाई मेरा लागि निर्धारण गर्नुहोस्, सजिलो बनाउनुहोस् र यसमा बरकत दिनुहोस्। र यदि तपाईंको ज्ञानमा यो काम मेरो दीन, जीवन र परिणामका लागि नराम्रो छ भने यसलाई मबाट र मलाई यसबाट टाढा गर्नुहोस्, र जहाँ भलाइ छ त्यो मेरा लागि निर्धारण गर्नुहोस्, अनि मलाई त्यसमा सन्तुष्ट पार्नुहोस्।", "कुनै वैध काममा भलाइ माग्न दुई रकअत नफ्लपछि।", "नबी ﷺ सहाबाहरूलाई हरेक काममा इस्तिखारा कुरआनको सूरह जस्तै सिकाउनुहुन्थ्यो।"),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बिका असबहना", "हे अल्लाह! तपाईंकै मद्दतले हामीले बिहान गर्यौँ र तपाईंकै मद्दतले साँझ गर्यौँ, तपाईंकै आदेशले बाँच्छौँ र मर्छौँ, र तपाईंतर्फ नै पुनरुत्थान छ।", "बिहान।", "नबी ﷺ सहाबाहरूलाई बिहान-साँझ यो सिकाउनुहुन्थ्यो।"),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बिका अमसैना", "हे अल्लाह! तपाईंकै मद्दतले हामीले साँझ गर्यौँ र तपाईंकै मद्दतले बिहान गर्यौँ, तपाईंकै आदेशले बाँच्छौँ र मर्छौँ, र तपाईंतर्फ नै फर्किनु छ।", "साँझ।", "नबी ﷺ सहाबाहरूलाई बिहान-साँझ यो सिकाउनुहुन्थ्यो।"),
        "dua_afiyah_morning" to DuaText("आफियतको दुआ", "हे अल्लाह! म तपाईंसँग संसार र आखिरतमा क्षमा र सुरक्षा माग्छु।", "नबी ﷺ बिहान-साँझ यो दुआ कहिल्यै छोड्नुहुन्नथ्यो।", "सुरक्षाभन्दा उत्तम कुरा कसैलाई दिइएको छैन।"),
        "dua_afini_fi_badani" to DuaText("शरीर, सुनाइ र दृष्टिको स्वास्थ्य", "हे अल्लाह! मेरो शरीरमा स्वास्थ्य दिनुहोस्, मेरो सुनाइमा स्वास्थ्य दिनुहोस्, मेरो दृष्टिमा स्वास्थ्य दिनुहोस्। तपाईंबाहेक कोही पूज्य छैन।", "बिहान र साँझ तीन-तीन पटक।", "स्वास्थ्य र इन्द्रियहरूको सुरक्षाको दुआ।"),
        "dua_ya_hayyu_aslih" to DuaText("मेरा सबै काम सुधारिदिनुहोस्", "हे सदा जीवित, हे धारक! तपाईंको कृपाले सहायता माग्छु, मेरा सबै काम सुधारिदिनुहोस् र मलाई पलक झिम्काउने बराबर पनि मेरो आफ्नै मनको भरमा नछोड्नुहोस्।", "नबी ﷺ ले फातिमा (र.) लाई बिहान-साँझ पढ्ने उपदेश दिनुभयो।", "हरेक काममा अल्लाहको मद्दतको माग।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवैरिया (र.) को तस्बीह", "अल्लाह पवित्र हुनुहुन्छ र प्रशंसा उहाँकै हो — उहाँका सृष्टिको संख्याबराबर, उहाँको प्रसन्नताअनुसार, उहाँको अर्शको तौलबराबर र उहाँका वचनहरूको मसीबराबर।", "बिहान तीन पटक — घण्टौँको जिक्रभन्दा भारी।", "यी चार वाक्य तीन पटक भन्नु बिहानदेखि मध्याह्नसम्मको जिक्रभन्दा तौलमा भारी छ।"),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहीमी", "हे अल्लाह! मुहम्मद ﷺ र मुहम्मदको परिवारमाथि कृपा बर्साउनुहोस् जसरी तपाईंले इब्राहीम (अ.) र इब्राहीमको परिवारमाथि बर्साउनुभयो, निश्चय नै तपाईं प्रशंसनीय, गौरवशाली हुनुहुन्छ। हे अल्लाह! मुहम्मद ﷺ र मुहम्मदको परिवारमाथि बरकत बर्साउनुहोस् जसरी तपाईंले इब्राहीम (अ.) र इब्राहीमको परिवारमाथि बर्साउनुभयो, निश्चय नै तपाईं प्रशंसनीय, गौरवशाली हुनुहुन्छ।", "नमाजमा र हरेक समय नबी ﷺ माथि दुरूद।", "जसले एक पटक दुरूद पठाउँछ, अल्लाहले उसमाथि दस कृपा बर्साउनुहुन्छ (मुस्लिम ४०८)।"),
        "dua_wudu_after" to DuaText("वुजूपछि", "म साक्षी दिन्छु कि अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, र मुहम्मद ﷺ उहाँका दास र रसूल हुनुहुन्छ। हे अल्लाह! मलाई तौबा गर्नेहरू र पवित्र रहनेहरूमध्ये बनाउनुहोस्।", "वुजू पूरा गरेपछि।", "जन्नतका आठै ढोका खोलिन्छन्, जुनबाट चाहे प्रवेश गर्न सक्छ।"),
        "dua_wudu_before" to DuaText("वुजूअघि", "अल्लाहको नाममा।", "वुजू सुरु गर्दा।", "जसले वुजूमा अल्लाहको नाम लिँदैन उसको वुजू (पूर्ण) हुँदैन।"),
        "dua_istiftah" to DuaText("सना (नमाजको सुरुको दुआ)", "हे अल्लाह! तपाईं पवित्र हुनुहुन्छ आफ्नो प्रशंसासहित, तपाईंको नाम बरकतमय छ, तपाईंको गरिमा उच्च छ र तपाईंबाहेक कोही पूज्य छैन।", "नमाज सुरु गर्दा, तकबीर-ए-तहरीमापछि तुरुन्तै।", "नमाजको मसनून सुरुको दुआ।"),
        "dua_ruku" to DuaText("रुकूमा", "मेरा महान रब पवित्र हुनुहुन्छ।", "रुकूमा कम्तीमा तीन पटक।", "रुकूको मसनून तस्बीह।"),
        "dua_sujood" to DuaText("सजदामा", "मेरा सर्वोच्च रब पवित्र हुनुहुन्छ।", "सजदामा कम्तीमा तीन पटक।", "दास सजदामा आफ्ना रबको सबैभन्दा नजिक हुन्छ (मुस्लिम ४८२)।"),
        "dua_rising_ruku" to DuaText("रुकूबाट उठ्दा", "जसले अल्लाहको प्रशंसा गर्छ अल्लाहले उसको सुन्नुहुन्छ। हे हाम्रा रब! सम्पूर्ण प्रशंसा तपाईंकै लागि हो।", "रुकूबाट उठ्दा र सिधा उभिएर।", "जसको 'रब्बना व लकल हम्द' फरिश्ताहरूसँग मिल्छ उसका पहिलेका पाप क्षमा।"),
        "dua_between_sajdas" to DuaText("दुई सजदाबीच", "हे मेरा रब! मलाई क्षमा गर्नुहोस्, हे मेरा रब! मलाई क्षमा गर्नुहोस्।", "दुई सजदाबीच बस्दा।", "जलसाको मसनून दुआ।"),
        "dua_before_salam_four" to DuaText("चार कुराबाट शरण (सलामअघि)", "हे अल्लाह! म तपाईंको शरण माग्छु जहन्नमको सजायबाट, चिहानको सजायबाट, जीवन र मृत्युको फित्नाबाट, र मसीह दज्जालको फित्नाको खराबीबाट।", "अन्तिम तशह्हुद र दुरूदपछि, सलामअघि।", "नबी ﷺ ले यी चार कुराबाट शरण माग्न आदेश दिनुभयो।"),
        "dua_qunoot_witr" to DuaText("वित्रमा कुनूत", "हे अल्लाह! जसलाई तपाईंले मार्गदर्शन दिनुभयो तिनीहरूमा मलाई मार्गदर्शन दिनुहोस्, जसलाई सुरक्षा दिनुभयो तिनीहरूमा मलाई सुरक्षा दिनुहोस्, जसको संरक्षण गर्नुभयो तिनीहरूमा मेरो संरक्षण गर्नुहोस्, जे दिनुभयो त्यसमा बरकत दिनुहोस्, र जे निर्णय गर्नुभयो त्यसको खराबीबाट बचाउनुहोस्। निश्चय नै तपाईं निर्णय गर्नुहुन्छ र तपाईंविरुद्ध निर्णय हुँदैन, र जसका तपाईं मित्र हुनुहुन्छ ऊ अपमानित हुँदैन। हे हाम्रा रब! तपाईं बरकतमय र उच्च हुनुहुन्छ।", "वित्र नमाजमा — नबी ﷺ ले हसन बिन अली (र.) लाई सिकाउनुभयो।", "वित्रको मसनून कुनूत। (हनफीहरूमा 'अल्लाहुम्मा इन्ना नस्तईनुका' पनि प्रसिद्ध छ।)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत (अल्लाहुम्मा इन्ना नस्तईनुका)", "हे अल्लाह! हामी तपाईंसँग मद्दत र क्षमा माग्छौँ, तपाईंमाथि ईमान ल्याउँछौँ र भरोसा गर्छौँ, तपाईंको उत्तम प्रशंसा गर्छौँ, तपाईंको धन्यवाद गर्छौँ, कृतघ्न हुँदैनौँ, र जसले तपाईंको अवज्ञा गर्छ उसलाई छोड्छौँ। हे अल्लाह! हामी तपाईंकै उपासना गर्छौँ, तपाईंकै लागि नमाज पढ्छौँ र सजदा गर्छौँ, तपाईंतर्फ दौडिन्छौँ, तपाईंको कृपाको आशा गर्छौँ र तपाईंको सजायदेखि डराउँछौँ; निश्चय नै तपाईंको सजाय काफिरहरूलाई पुग्नेवाला छ।", "वित्रमा — हनफीहरूको अभ्यास।", "उमर (र.) बाट कुनूतमा वर्णित।"),
        "dua_sleep_aslamtu" to DuaText("सुत्नुअघिका अन्तिम शब्द", "हे अल्लाह! मैले आफूलाई तपाईंमा समर्पण गरेँ, आफ्नो काम तपाईंको जिम्मामा सुम्पेँ, आफ्नो पिठ्युँ तपाईंको शरणमा दिएँ, तपाईंप्रतिको आशा र डरका साथ। तपाईंबाट बच्ने कुनै शरण र मुक्ति छैन तपाईंकै तर्फबाहेक। तपाईंले उतार्नुभएको पुस्तक र तपाईंले पठाउनुभएको नबीमाथि मैले ईमान ल्याएँ।", "वुजू गरेर दायाँ कोल्टे पल्टेर — सबैभन्दा अन्तिम शब्द।", "त्यही रात मृत्यु भए फितरत (इस्लाम) मा मृत्यु हुनेछ।"),
        "dua_waking_night" to DuaText("राति ब्युँझँदा", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, राज्य र प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ। सम्पूर्ण प्रशंसा अल्लाहका लागि, अल्लाह पवित्र हुनुहुन्छ, अल्लाहबाहेक कोही पूज्य छैन, अल्लाह सबैभन्दा महान हुनुहुन्छ, र अल्लाहबाहेक कुनै शक्ति र सामर्थ्य छैन। हे अल्लाह! मलाई क्षमा गर्नुहोस्।", "राति ब्युँझँदा।", "दुआ स्वीकार हुन्छ, र वुजू गरेर नमाज पढे नमाज स्वीकार हुन्छ।"),
        "dua_hamm_ibn_masud" to DuaText("दुःखको दुआ (इब्न मसऊद)", "हे अल्लाह! म तपाईंको दास हुँ, तपाईंको दासको छोरा, तपाईंकी दासीको छोरा। मेरो निधार तपाईंको हातमा छ, ममाथि तपाईंको आदेश लागू हुन्छ, मेरो बारेमा तपाईंको निर्णय न्यायपूर्ण छ। म तपाईंसँग तपाईंको हरेक त्यो नामको आधारमा याचना गर्छु जुन तपाईंले आफ्नो लागि राख्नुभयो, वा आफ्नो पुस्तकमा उतार्नुभयो, वा आफ्नो कुनै सृष्टिलाई सिकाउनुभयो, वा आफूसँग अदृश्य ज्ञानमा सुरक्षित राख्नुभयो — कि कुरआनलाई मेरो हृदयको वसन्त, मेरो छातीको प्रकाश, मेरो दुःखको उपचार र मेरो चिन्ता हटाउने बनाइदिनुहोस्।", "दुःख र चिन्तामा — अल्लाहले दुःखलाई खुसीमा बदलिदिनुहुन्छ।", "अल्लाहले उसको चिन्ता र दुःख हटाएर खुसी दिनुहुन्छ।"),
        "dua_difficulty_sahl" to DuaText("जब कुनै काम कठिन हुन्छ", "हे अल्लाह! केही पनि सजिलो छैन जबसम्म तपाईंले सजिलो बनाउनुहुन्न, र तपाईंले चाहनुभयो भने कठिनलाई सजिलो बनाउनुहुन्छ।", "कुनै काम कठिन लागेमा।", "परीक्षा र कठिन कामहरूमा सहजता।"),
        "dua_musibah" to DuaText("संकटमा (इस्तिरजा)", "हामी अल्लाहकै हौँ र उहाँतर्फ नै फर्कनेवाला छौँ। हे अल्लाह! मेरो संकटमा मलाई प्रतिफल दिनुहोस् र यसभन्दा उत्तम विकल्प दिनुहोस्।", "कुनै पनि हानि वा संकटमा।", "अल्लाहले अवश्य उत्तम विकल्प दिनुहुन्छ — उम्मे सलमा (र.) ले नबी ﷺ पाउनुभयो।"),
        "dua_debt" to DuaText("ऋणमुक्तिका लागि", "हे अल्लाह! तपाईंको हलालद्वारा मलाई हरामबाट बचाएर पर्याप्त हुनुहोस्, र आफ्नो अनुग्रहले मलाई तपाईंबाहेक सबैबाट निरपेक्ष बनाउनुहोस्।", "ऋण तिर्नका लागि — अली (र.) ले सिकाउनुभयो।", "पहाडजत्रो ऋण भए पनि अल्लाहले तिराइदिनुहुन्छ।"),
        "dua_anger" to DuaText("रिसको समयमा", "म धिक्कारिएको शैतानबाट अल्लाहको शरण माग्छु।", "रिस उठ्दा।", "नबी ﷺ ले भन्नुभयो: यदि उसले यो भन्यो भने उसको रिस जानेछ।"),
        "dua_waswasa" to DuaText("ईमानमा वसवसाविरुद्ध", "म अल्लाह र उहाँका रसूलहरूमाथि ईमान ल्याएँ।", "ईमानबारे शैतानी वसवसा आएमा।", "वसवसा आएमा यो भन्नुहोस् र रोकिनुहोस् (अऊजु बिल्लाह पनि पढ्नुहोस्)।"),
        "dua_travel_full" to DuaText("यात्राको पूर्ण दुआ", "हे अल्लाह! हामी यस यात्रामा तपाईंसँग पुण्य र तक्वा माग्छौँ र यस्तो कर्म जुन तपाईंलाई मन पर्छ। हे अल्लाह! हाम्रो यो यात्रा सजिलो बनाइदिनुहोस् र यसको दूरी छोटो पारिदिनुहोस्। हे अल्लाह! तपाईं नै यात्राका साथी र परिवारका रक्षक हुनुहुन्छ।", "यात्रामा निस्कँदा, 'सुब्हानल्लजी सख्खरा' पछि।", "यात्राको पूर्ण मसनून दुआ।"),
        "dua_return_travel" to DuaText("यात्राबाट फर्कँदा", "हामी फर्कनेवाला, तौबा गर्नेवाला, उपासना गर्नेवाला र आफ्ना रबको प्रशंसा गर्नेवाला हौँ।", "यात्राबाट फर्कँदा।", "नबी ﷺ यात्राबाट फर्कँदा यो भन्नुहुन्थ्यो।"),
        "dua_farewell_traveller" to DuaText("यात्रीलाई बिदाइ", "म तिम्रो दीन, तिम्रो अमानत र तिम्रा कर्मको परिणाम अल्लाहको जिम्मामा सुम्पन्छु।", "यात्रीलाई बिदा गर्दा।", "अल्लाहको जिम्मामा सुम्पिएको कुरा खेर जाँदैन।"),
        "dua_entering_town" to DuaText("कुनै ठाउँमा बस्दा", "म अल्लाहका पूर्ण वचनहरूको शरण माग्छु उहाँका सबै सृष्टिको खराबीबाट।", "कुनै ठाउँमा बास बस्दा वा नयाँ सहरमा पुग्दा।", "त्यहाँबाट नहिँडुन्जेल कुनै कुराले हानि गर्दैन।"),
        "dua_boarding_ship" to DuaText("डुंगा/सवारीमा चढ्दा", "अल्लाहकै नाममा यसको चलाइ र रोकाइ छ, निश्चय नै मेरा रब क्षमाशील, दयालु हुनुहुन्छ।", "डुंगा वा सवारीमा चढ्दा — नूह (अ.) को वचन।", "कुरआनी आयत — नूह (अ.) को डुंगाको दुआ।"),
        "dua_istighfar_hayyul_qayyum" to DuaText("हय्युल कय्यूमसहित इस्तिगफार", "म त्यो अल्लाहसँग क्षमा माग्छु जसबाहेक कोही पूज्य छैन, जो सदा जीवित र धारक हुनुहुन्छ, र उहाँतर्फ तौबा गर्छु।", "तौबाका लागि।", "पाप क्षमा हुन्छन्, चाहे ऊ युद्धभूमिबाट भागेको किन नहोस्।"),
        "dua_rabbighfir_warham" to DuaText("रब्बिग्फिर वरहम", "हे मेरा रब! क्षमा गर्नुहोस् र दया गर्नुहोस्, र तपाईं सर्वोत्तम दया गर्नुहुने हुनुहुन्छ।", "कुरआनी दुआ — क्षमा र कृपा।", "सूरह मोमिनूनको अन्तिम आयत।"),
        "dua_majlis_kaffarah" to DuaText("सभाको प्रायश्चित्त", "हे अल्लाह! तपाईं पवित्र हुनुहुन्छ आफ्नो प्रशंसासहित। म साक्षी दिन्छु कि तपाईंबाहेक कोही पूज्य छैन। म तपाईंसँग क्षमा माग्छु र तपाईंतर्फ तौबा गर्छु।", "सभा/बैठकबाट उठ्दा।", "सभामा भएका गलत कुराहरूको प्रायश्चित्त हुन्छ।"),
        "dua_jami_forgiveness" to DuaText("व्यापक क्षमा", "हे अल्लाह! मेरो गल्ती, मेरो अज्ञानता, मेरो काममा मेरो अति, र जुन तपाईं मभन्दा बढी जान्नुहुन्छ ती सबै क्षमा गर्नुहोस्।", "नबी ﷺ को व्यापक दुआ।", "नबी ﷺ यो दुआ गर्नुहुन्थ्यो।"),
        "dua_parents_nuh" to DuaText("आमाबुबाका लागि नूह (अ.) को दुआ", "हे मेरा रब! मलाई, मेरा आमाबुबालाई, जो ईमानसहित मेरो घरमा प्रवेश गर्छ उसलाई, र सबै मोमिन पुरुष र महिलालाई क्षमा गर्नुहोस्।", "आमाबुबा र मोमिनहरूका लागि।", "नूह (अ.) को दुआ।"),
        "dua_shukr_parents" to DuaText("आमाबुबाको कृपाको धन्यवाद र असल सन्तान", "हे मेरा रब! मलाई सामर्थ्य दिनुहोस् कि म तपाईंको त्यो कृपाको धन्यवाद गरूँ जुन तपाईंले ममाथि र मेरा आमाबुबामाथि गर्नुभयो, र यस्तो असल कर्म गरूँ जुन तपाईंलाई मन पर्छ, र मेरा सन्तानलाई पनि असल बनाउनुहोस्। म तपाईंतर्फ तौबा गर्छु र म आज्ञाकारीहरूमध्येको हुँ।", "चालीस वर्षको उमेरको कुरआनी दुआ।", "कृतज्ञता, असल कर्म र सन्तानको सुधार — सबै एउटै दुआमा।"),
        "dua_intimacy" to DuaText("वैवाहिक सम्बन्धअघि", "अल्लाहको नाममा। हे अल्लाह! हामीलाई शैतानबाट टाढा राख्नुहोस् र तपाईंले हामीलाई जे (सन्तान) दिनुहुन्छ त्यसलाई पनि शैतानबाट टाढा राख्नुहोस्।", "पति-पत्नीको मिलनअघि।", "सन्तान निर्धारित भएमा शैतानले उसलाई कहिल्यै हानि गर्दैन।"),
        "dua_ibrahim_children_protection" to DuaText("घर र सन्तानको सुरक्षा", "हे मेरा रब! यो सहरलाई सुरक्षित बनाउनुहोस् र मलाई र मेरा सन्तानलाई मूर्तिपूजाबाट टाढा राख्नुहोस्।", "इब्राहीम (अ.) को दुआ — सहर र सन्तानको सुरक्षा।", "तौहीदमा कायम रहने दुआ।"),
        "dua_drinking_milk" to DuaText("दूध पिउँदा", "हे अल्लाह! हाम्रा लागि यसमा बरकत दिनुहोस् र हामीलाई अझ बढी दिनुहोस्।", "दूध पिउँदा।", "दूध खाना र पेय दुवैका लागि पर्याप्त हुन्छ।"),
        "dua_iftar_host" to DuaText("कसैको घरमा इफ्तार गर्दा", "तिम्रो घरमा रोजेदारहरूले इफ्तार गरून्, असल मानिसहरूले तिम्रो खाना खाऊन् र फरिश्ताहरूले तिम्रा लागि दुआ गरून्।", "कसैको घरमा इफ्तार गर्दा।", "आतिथेयका लागि नबी ﷺ को दुआ।"),
        "dua_seeing_first_fruit" to DuaText("मौसमको पहिलो फल देख्दा", "हे अल्लाह! हाम्रा फलहरूमा, हाम्रो सहरमा, हाम्रो साअ र मुद्द (नापतौल) मा बरकत दिनुहोस्।", "मौसमको पहिलो फल देखेर।", "जीविका र सहरमा बरकतको दुआ।"),
        "dua_good_news" to DuaText("शुभ समाचार पाउँदा", "सम्पूर्ण प्रशंसा त्यो अल्लाहका लागि जसको कृपाले राम्रा कामहरू पूरा हुन्छन्।", "खुसीको खबर पाउँदा (र सजदा-ए-शुक्र)।", "नबी ﷺ मनपर्ने कुरा देख्दा यो भन्नुहुन्थ्यो।"),
        "dua_looking_mirror" to DuaText("ऐना हेर्दा", "हे अल्लाह! जसरी तपाईंले मेरो रूप सुन्दर बनाउनुभयो, त्यसरी नै मेरो चरित्र पनि सुन्दर बनाउनुहोस्।", "ऐना हेर्दा।", "नबी ﷺ यो दुआ गर्नुहुन्थ्यो (ऐनाको सर्तबिना पनि प्रमाणित छ)।"),
        "dua_rabbana_taqabbal" to DuaText("कर्मको स्वीकृति", "हे हाम्रा रब! हामीबाट स्वीकार गर्नुहोस्, निश्चय नै तपाईं सुन्नुहुने, जान्नुहुने हुनुहुन्छ। र हाम्रो तौबा स्वीकार गर्नुहोस्, निश्चय नै तपाईं तौबा स्वीकार गर्नुहुने, दयालु हुनुहुन्छ।", "इब्राहीम र इस्माईल (अ.) ले काबा निर्माण गर्दा माग्नुभयो।", "हरेक असल कर्मपछि स्वीकृतिको दुआ।"),
    )
}
